/** A connection to a list of `MmSupply` values. */
export type MmSuppliesConnection = {
  __typename?: 'MmSuppliesConnection';
  /** Aggregates across the matching connection (ignoring before/after/first/last/offset) */
  aggregates?: Maybe<MmSupplyAggregates>;
  /** A list of edges which contains the `MmSupply` and cursor to aid in pagination. */
  edges: Array<MmSuppliesEdge>;
  /** Grouped aggregates across the matching connection (ignoring before/after/first/last/offset) */
  groupedAggregates?: Maybe<Array<MmSupplyAggregates>>;
  /** A list of `MmSupply` objects. */
  nodes: Array<Maybe<MmSupply>>;
  /** Information to aid in pagination. */
  pageInfo: PageInfo;
  /** The count of *all* `MmSupply` you could get from the connection. */
  totalCount: Scalars['Int']['output'];
};


/** A connection to a list of `MmSupply` values. */
export type MmSuppliesConnectionGroupedAggregatesArgs = {
  groupBy: Array<MmSupplyGroupBy>;
  having?: InputMaybe<MmSupplyHavingInput>;
};

/** A `MmSupply` edge in the connection. */
export type MmSuppliesEdge = {
  __typename?: 'MmSuppliesEdge';
  /** A cursor for use in pagination. */
  cursor?: Maybe<Scalars['Cursor']['output']>;
  /** The `MmSupply` at the end of the edge. */
  node?: Maybe<MmSupply>;
};

