export type OmnipoolAssetsYieldMetricsFilter = {
  assetIds?: InputMaybe<Array<Scalars['String']['input']>>;
  interval?: InputMaybe<YieldMetricsInterval>;
};

export type OmnipoolAssetsYieldMetricsResponse = {
  __typename?: 'OmnipoolAssetsYieldMetricsResponse';
  nodes: Array<Maybe<OmnipoolAssetYieldMetricsAggregated>>;
  totalCount: Scalars['Int']['output'];
};

export type OmnipoolAverageAggregates = {
  __typename?: 'OmnipoolAverageAggregates';
  /** Mean average of destroyedAtParaBlockHeight across the matching connection */
  destroyedAtParaBlockHeight?: Maybe<Scalars['BigFloat']['output']>;
};

/**
 * A condition to be used against `Omnipool` object types. All fields are tested
 * for equality and combined with a logical ‘and.’
 */
export type OmnipoolCondition = {
  /** Checks for equality with the object’s `accountId` field. */
  accountId?: InputMaybe<Scalars['String']['input']>;
  /** Checks for equality with the object’s `destroyedAtBlockId` field. */
  destroyedAtBlockId?: InputMaybe<Scalars['String']['input']>;
  /** Checks for equality with the object’s `destroyedAtParaBlockHeight` field. */
  destroyedAtParaBlockHeight?: InputMaybe<Scalars['Int']['input']>;
  /** Checks for equality with the object’s `id` field. */
  id?: InputMaybe<Scalars['String']['input']>;
  /** Checks for equality with the object’s `isDestroyed` field. */
  isDestroyed?: InputMaybe<Scalars['Boolean']['input']>;
};

export type OmnipoolDistinctCountAggregates = {
  __typename?: 'OmnipoolDistinctCountAggregates';
  /** Distinct count of accountId across the matching connection */
  accountId?: Maybe<Scalars['BigInt']['output']>;
  /** Distinct count of destroyedAtBlockId across the matching connection */
  destroyedAtBlockId?: Maybe<Scalars['BigInt']['output']>;
  /** Distinct count of destroyedAtParaBlockHeight across the matching connection */
  destroyedAtParaBlockHeight?: Maybe<Scalars['BigInt']['output']>;
  /** Distinct count of id across the matching connection */
  id?: Maybe<Scalars['BigInt']['output']>;
  /** Distinct count of isDestroyed across the matching connection */
  isDestroyed?: Maybe<Scalars['BigInt']['output']>;
};

/** A filter to be used against `Omnipool` object types. All fields are combined with a logical ‘and.’ */
export type OmnipoolFilter = {
  /** Filter by the object’s `accountId` field. */
  accountId?: InputMaybe<StringFilter>;
  /** Checks for all expressions in this list. */
  and?: InputMaybe<Array<OmnipoolFilter>>;
  /** Filter by the object’s `destroyedAtBlockId` field. */
  destroyedAtBlockId?: InputMaybe<StringFilter>;
  /** Filter by the object’s `destroyedAtParaBlockHeight` field. */
  destroyedAtParaBlockHeight?: InputMaybe<IntFilter>;
  /** Filter by the object’s `id` field. */
  id?: InputMaybe<StringFilter>;
  /** Filter by the object’s `isDestroyed` field. */
  isDestroyed?: InputMaybe<BooleanFilter>;
  /** Negates the expression. */
  not?: InputMaybe<OmnipoolFilter>;
  /** Checks for any expressions in this list. */
  or?: InputMaybe<Array<OmnipoolFilter>>;
};

