export const GetBroadcastSwappedEventData = gql`
    query GetBroadcastSwappedEventData($filter: EventFilter) {
  events(filter: $filter) {
    nodes {
      args
      swaps {
        nodes {
          id
          swapper {
            id
          }
          filler {
            id
          }
          operationType
          operationId
          swapInputs {
            nodes {
              assetId
              amount
              asset {
                assetRegistryId
              }
            }
          }
          swapOutputs {
            nodes {
              assetId
              amount
              asset {
                assetRegistryId
              }
            }
          }
          swapFees {
            nodes {
              assetId
              amount
              recipientId
              asset {
                assetRegistryId
              }
            }
          }
        }
      }
    }
  }
}
    `;
export const GetMoneyMarketEventSupplyData = gql`
    query GetMoneyMarketEventSupplyData($filter: MoneyMarketEventFilter) {
  moneyMarketEvents(filter: $filter) {
    nodes {
      eventName
      paraBlockHeight
      supply {
        amount
        asset {
          id
          evmAddress
        }
        account {
          boundEvmAddress
        }
      }
    }
  }
}
    `;
export const GetMoneyMarketEventBorrowData = gql`
    query GetMoneyMarketEventBorrowData($filter: MoneyMarketEventFilter) {
  moneyMarketEvents(filter: $filter) {
    nodes {
      eventName
      paraBlockHeight
      borrow {
        amount
        asset {
          id
          evmAddress
        }
        account {
          boundEvmAddress
        }
      }
    }
  }
}
    `;
export const GetAccountData = gql`
    query GetAccountData($filter: AccountFilter) {
  accounts(filter: $filter) {
    nodes {
      id
    }
  }
}
    `;
export const GetProcessorStatusData = gql`
    query GetProcessorStatusData($filter: ProcessorStatusFilter) {
  processorStatuses(filter: $filter) {
    nodes {
      latestProcessedBlock
    }
  }
}
    `;